const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const washingtonDc = ee.Geometry.Point([-77.0369, 38.9072]); // Washington D.C. coordinates
  const scale = 11132; // Approx. 10km for ERA5-Land data resolution (0.1 degree)
  const bandName = 'temperature_2m'; // 2m air temperature in Kelvin

  const date1 = '2019-01-29';
  const date2 = '2019-02-05';

  // 2. Data Acquisition & Check
  const era5Land = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY');

  // Filter for the first date
  const col1 = era5Land.filterDate(date1, ee.Date(date1).advance(1, 'day'))
                       .select(bandName);
  const size1 = col1.size().getInfo();

  if (size1 === 0) {
    console.log(`No ERA5-Land hourly data found for ${date1}.`);
    console.log("C1");
    return;
  }
  const meanTemp1K = col1.mean(); // Mean of hourly temperatures for the day

  // Filter for the second date
  const col2 = era5Land.filterDate(date2, ee.Date(date2).advance(1, 'day'))
                       .select(bandName);
  const size2 = col2.size().getInfo();

  if (size2 === 0) {
    console.log(`No ERA5-Land hourly data found for ${date2}.`);
    console.log("C1");
    return;
  }
  const meanTemp2K = col2.mean(); // Mean of hourly temperatures for the day

  // 3. Processing (Calculate pixel count to detect C2, though unlikely for global reanalysis)
  // For ERA5-Land, a single image is sufficient for a global average.
  // We'll calculate the mean over the Washington D.C. point.

  const reducer = ee.Reducer.mean();

  const temp1K_val = meanTemp1K.reduceRegion({
    reducer: reducer,
    geometry: washingtonDc,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName);

  const temp2K_val = meanTemp2K.reduceRegion({
    reducer: reducer,
    geometry: washingtonDc,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName);

  const finalTemp1K = await ee.data.computeValue(temp1K_val);
  const finalTemp2K = await ee.data.computeValue(temp2K_val);

  // Check for C2 (No valid pixels) or C3 (Calculation Failure - None/NaN)
  if (finalTemp1K === null || finalTemp2K === null) {
      console.log("C3");
      return;
  }

  // Convert Kelvin to Celsius
  const temp1C = finalTemp1K - 273.15;
  const temp2C = finalTemp2K - 273.15;

  // 4. Calculation
  const temperatureDifference = Math.abs(temp1C - temp2C);

  // 5. Validation & Final Answer
  console.log(`Images for ${date1}: ${size1} (Mean K: ${finalTemp1K.toFixed(2)}, Mean C: ${temp1C.toFixed(2)})`);
  console.log(`Images for ${date2}: ${size2} (Mean K: ${finalTemp2K.toFixed(2)}, Mean C: ${temp2C.toFixed(2)})`);
  console.log(`Calculated temperature difference: ${temperatureDifference.toFixed(2)} °C`);

  if (isNaN(temperatureDifference)) {
    console.log("C3"); // Calculation resulted in NaN
  } else if (temperatureDifference >= 24) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
